-- migrations/0003_fts_search.sql
-- Full-Text Search (FTS5) external-content index over restaurants (EN + spaced CJK + Address + District)
-- Eliminates 42,812-row full table scans (~2,500 shadow rows total)

DROP TRIGGER IF EXISTS restaurants_fts_ai;
DROP TRIGGER IF EXISTS restaurants_fts_ad;
DROP TRIGGER IF EXISTS restaurants_fts_au;
DROP TABLE IF EXISTS restaurants_fts;
DROP VIEW IF EXISTS restaurants_fts_view;

CREATE VIEW restaurants_fts_view AS
