  address_en,
  district
FROM restaurants;

CREATE VIRTUAL TABLE restaurants_fts USING fts5(
  name_en,
  name_tc_spaced,
  address_en,
  district,
  content='restaurants_fts_view',
  content_rowid='rowid',
  tokenize='unicode61 remove_diacritics 2',
  columnsize=0
);

